},"notebook.1.tag":{"kind":"text","max":700},"notebook.1.title":{"kind":"text","max":700},"notebook.1.linkLabel":{"kind":"text","max":700},"notebook.2.tag":{"kind":"text","max":700},"notebook.2.title":{"kind":"text","max":700},"notebook.2.linkLabel":{"kind":"text","max":700},"final.eyebrow":{"kind":"text","max":700},"final.title":{"kind":"text","max":700},"final.emphasis":{"kind":"text","max":700},"final.book":{"kind":"text","max":700},"final.image":{"kind":"image","max":2000},"final.alt":{"kind":"text","max":700},"nav.0.label":{"kind":"text","max":700},"nav.0.link":{"kind":"link","max":2000},"nav.1.label":{"kind":"text","max":700},"nav.1.link":{"kind":"link","max":2000},"nav.2.label":{"kind":"text","max":700},"nav.2.link":{"kind":"link","max":2000},"nav.3.label":{"kind":"text","max":700},"nav.3.link":{"kind":"link","max":2000},"nav.4.label":{"kind":"text","max":700},"nav.4.link":{"kind":"link","max":2000},"nav.book":{"kind":"text","max":700},"nav.mobileBook":{"kind":"text","max":700},"nav.mobileMap":{"kind":"text","max":700},"footer.line1":{"kind":"text","max":700},"footer.line2":{"kind":"text","max":700},"footer.0.label":{"kind":"text","max":700},"footer.0.link":{"kind":"link","max":2000},"footer.1.label":{"kind":"text","max":700},"footer.1.link":{"kind":"link","max":2000},"footer.2.label":{"kind":"text","max":700},"footer.2.link":{"kind":"link","max":2000},"footer.3.label":{"kind":"text","max":700},"footer.3.link":{"kind":"link","max":2000},"footer.4.label":{"kind":"text","max":700},"footer.4.link":{"kind":"link","max":2000},"footer.5.label":{"kind":"text","max":700},"footer.5.link":{"kind":"link","max":2000},"footer.location":{"kind":"text","max":700},"footer.language":{"kind":"text","max":700},"footer.contact":{"kind":"text","max":700},"seo.title":{"kind":"text","max":700},"seo.description":{"kind":"text","max":700},"seo.image":{"kind":"image","max":2000},"seo.alt":{"kind":"text","max":700}}'::jsonb; k text; v text;
begin
 if jsonb_typeof(p_data) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_data)) <> (select count(*) from jsonb_object_keys(spec)) then return false; end if;
 for k in select jsonb_object_keys(spec) loop
  v := p_data->>k;
  if jsonb_typeof(p_data->k) is distinct from 'string' or length(btrim(v))=0 or length(v)>(spec->k->>'max')::integer then return false; end if;
  if spec->k->>'kind'='link' and v !~ '^/($|#(route|booking|destinations)$|(tour|live|explore|book|credits|admin)(#(faq|timetable|centre|castle|lake|bridge))?$|explore/(centre|castle|lake|bridge)$)' then return false; end if;
  if spec->k->>'kind'='image' and v !~ '^/images/[a-zA-Z0-9/_-]+[.](webp|png|jpg|jpeg|avif)$' and v !~ '^https://[a-z0-9-]+[.]supabase[.]co/storage/v1/object/public/website-media/[a-f0-9-]+/[a-f0-9-]+[.](webp|png|jpg|avif)$' then return false; end if;
 end loop;
 return true;
end $$;

create or replace function public.save_catalog_v1(p_operator_id uuid,p_actor_id uuid,p_entity text,p_id uuid,p_data jsonb,p_delete boolean default false)
returns uuid language plpgsql set search_path='' as $$
declare saved uuid := coalesce(p_id,gen_random_uuid()); changed integer;
begin
  if not exists(select 1 from public.staff_profiles where operator_id=p_operator_id and id=p_actor_id and is_active and role in ('owner','admin')) then
    raise exception 'Catalog permission required' using errcode='42501'; end if;
  if p_entity not in ('product','supplier','stop') or p_entity is null or jsonb_typeof(p_data) is distinct from 'object' then
    raise exception 'Invalid catalog request' using errcode='22023'; end if;
  if p_delete then
    if p_id is null then raise exception 'Record required' using errcode='22023'; end if;
    case p_entity
      when 'product' then update public.products set status='archived' where operator_id=p_operator_id and id=p_id;
      when 'supplier' then delete from public.suppliers where operator_id=p_operator_id and id=p_id;
      when 'stop' then delete from public.stops where operator_id=p_operator_id and id=p_id;
    end case;
    get diagnostics changed=row_count;
    if changed<>1 then raise exception 'Record unavailable' using errcode='P0002'; end if;
  else
    if length(btrim(coalesce(p_data->>'name',p_data->>'title',''))) not between 1 and 200 then
      raise exception 'Name or title required' using errcode='22023'; end if;
    if p_entity='product' then
      if p_data->>'status' not in ('draft','published','archived') or p_data->>'status' is null
        or p_data->>'type' not in ('van_tour','boat_trip','attraction_ticket') or p_data->>'type' is null
        or length(coalesce(p_data->>'slug','')) not between 1 and 200
        or length(coalesce(p_data->>'inclusions',''))>700 or length(coalesce(p_data->>'meta_title',''))>200 or length(coalesce(p_data->>'meta_description',''))>500
        or (p_data->>'status'='published' and (length(btrim(coalesce(p_data->>'meta_title','')))=0 or length(btrim(coalesce(p_data->>'meta_description','')))=0))
        or (nullif(p_data->>'og_image','') is not null and (p_data->>'og_image' !~ '^https://[^[:space:]]+$' or length(btrim(coalesce(p_data->>'og_image_alt','')))=0)) then
        raise exception 'Invalid product or SEO fields' using errcode='22023'; end if;
      if p_id is null then
        insert into public.products(id,operator_id,title,slug,type) values(saved,p_operator_id,btrim(p_data->>'title'),p_data->>'slug',p_data->>'type');
      end if;
      update public.products set title=btrim(p_data->>'title'),slug=p_data->>'slug',type=p_data->>'type',status=p_data->>'status',
        inclusions=case when p_data ? 'inclusions' then nullif(p_data->>'inclusions','') else inclusions end, supplier_id=nullif(p_data->>'supplier_id','')::uuid,meta_title=nullif(btrim(p_data->>'meta_title'),''),meta_description=nullif(btrim(p_data->>'meta_description'),''),
        og_image=nullif(p_data->>'og_image',''),og_image_alt=nullif(btrim(p_data->>'og_image_alt'),'') where operator_id=p_operator_id and id=saved;
    elsif p_entity='supplier' then
      if p_data->>'type' not in ('owned','partner') or p_data->>'type' is null then raise exception 'Invalid supplier type' using errcode='22023'; end if;
      if p_id is null then insert into public.suppliers(id,operator_id,name,type) values(saved,p_operator_id,btrim(p_data->>'name'),p_data->>'type'); end if;
      update public.suppliers set name=btrim(p_data->>'name'),type=p_data->>'type' where operator_id=p_operator_id and id=saved;
    else
      if p_id is null then insert into public.stops(id,operator_id,product_id,name,lat,lng,sort_order)
        values(saved,p_operator_id,(p_data->>'product_id')::uuid,btrim(p_data->>'name'),(p_data->>'lat')::double precision,(p_data->>'lng')::double precision,(p_data->>'sort_order')::integer); end if;
      update public.stops set product_id=(p_data->>'product_id')::uuid,name=btrim(p_data->>'name'),lat=(p_data->>'lat')::double precision,
        lng=(p_data->>'lng')::double precision,sort_order=(p_data->>'sort_order')::integer where operator_id=p_operator_id and id=saved;
    end if;
    get diagnostics changed=row_count;
    if changed<>1 then raise exception 'Record unavailable' using errcode='P0002'; end if;
  end if;
  perform public.record_domain_activity(p_operator_id,p_actor_id,'catalog:'||gen_random_uuid()::text,p_entity,saved,
    'catalog.changed',jsonb_build_object('entity',p_entity,'id',saved),'catalog.changed',jsonb_build_object('operation',case when p_delete then 'remove' else 'save' end));
  return saved;
end;
$$;

create or replace function public.read_public_homepage_v1(p_operator_id uuid, p_product_slug text)
returns jsonb language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'version', 1,
    'operator', jsonb_build_object('id', o.id, 'name', o.name, 'timezone', o.timezone),
    'service_date', (statement_timestamp() at time zone o.timezone)::date,
    'product', (select jsonb_build_object('id', p.id, 'title', p.title, 'slug', p.slug,
      'description', p.meta_description, 'meta_title',p.meta_title,'og_image',p.og_image,'og_image_alt',p.og_image_alt,'inclusions',p.inclusions,
      'stops', '[]'::jsonb)
      from public.products p where p.operator_id = o.id and p.slug = p_product_slug
        and p.status = 'published' and p.type = 'van_tour'),
    'content', coalesce((select jsonb_agg(jsonb_build_object('slug', c.slug, 'title', c.title,
      'text', c.body->>'text', 'meta_title', c.meta_title, 'meta_description', c.meta_description,'og_image',c.og_image,'og_image_alt',c.og_image_alt) order by c.slug)
      from public.content_pages c where c.operator_id = o.id and c.status = 'published'
        and c.body->>'format' = 'plain_text' and c.body->'version' = '1'::jsonb
        and jsonb_typeof(c.body->'text') = 'string'
        and c.slug in (
          'explore-centre', 'explore-castle', 'explore-lake', 'explore-bridge')), '[]'::jsonb)
  ) from public.operators o where o.id = p_operator_id;
$$;

